INSERT INTO public.glossary_terms
("id", "term", "aliases", "definition", "learnMoreUrl", "isActive", "createdAt", "updatedAt")
VALUES
  ('cg26c_3efb0f92ddb309126f19b8', 'Abatement policy', ARRAY[]::text[], 'A government measure intended to limit environmental harm, such as pollution standards, subsidies for cleaner technology or emissions charges.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_fec5538a0ff2fe9a3dc15c', 'Accountability in governance', ARRAY[]::text[], 'The obligation of public or private decision-makers to explain and answer for their actions to those entitled to hold them responsible.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_057db935e5b5df8362d60f', 'Accounting profit', ARRAY[]::text[], 'A firm''s revenue minus explicit accounting expenses, including recorded depreciation. It excludes some opportunity costs included in economic profit.', 'https://openstax.org/books/principles-economics-3e/pages/7-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_d925d29a13413a7e787787', 'Adaptation gap', ARRAY[]::text[], 'The difference between adaptation already implemented and the level required to reach a society''s chosen climate-risk or resilience objectives.', 'https://www.ipcc.ch/report/ar6/wg2/chapter/annex-ii/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_9a59ff0ee26a2c29567d1d', 'Adaptation limit', ARRAY[]::text[], 'A point at which climate risks or harms cannot be avoided through adaptation, either because options do not exist or cannot currently be implemented.', 'https://www.ipcc.ch/report/ar6/wg2/chapter/annex-ii/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_aee333a4837029dffb2396', 'Adaptive expectations', ARRAY[]::text[], 'An approach in which people update forecasts gradually using past observations, such as adjusting expected inflation after seeing recent price rises.', 'https://openstax.org/books/principles-economics-3e/pages/26-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_84f7d90f0fea0f35c0d155', 'Aggregate investment function', ARRAY[]::text[], 'A relationship describing how total business investment responds to influences such as the cost of borrowing and expected profitability.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_7e9741a37ab710c3aa4b8b', 'Aggregate production function', ARRAY[]::text[], 'A model linking total economic output to labour, capital and technological productivity. Economists use it to analyse the sources of long-term growth.', 'https://openstax.org/books/principles-economics-3e/pages/20-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_3fac3c4cecf143f91bba44', 'Allocative efficiency', ARRAY[]::text[], 'A situation in which resources are directed towards the mix of goods and services people value most, given the economy''s constraints. It is distinct from producing at the lowest possible cost.', 'https://openstax.org/books/principles-economics-3e/pages/2-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_fb75220f44a85db49baa56', 'Altruism', ARRAY[]::text[], 'A willingness to incur a personal cost in order to benefit another person, without requiring a matching benefit in return.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_d4f48dd439e2d03a3b8e24', 'Asset price bubble', ARRAY[]::text[], 'An extended increase in asset prices driven partly by expectations of further increases, rather than changes in underlying expected cash flows or fundamentals.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_205d64ff9b580aadbf4829', 'Automation', ARRAY[]::text[], 'The use of machines or software to perform tasks previously carried out by people, changing production costs, skill requirements and demand for different kinds of work.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_1321f182c347db8f89bfe7', 'Autonomous consumption', ARRAY[]::text[], 'Household spending that does not depend on current income within a simple consumption model, such as basic spending financed from savings or borrowing.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_c9fae474957a81c9338c5f', 'Autonomous demand', ARRAY[]::text[], 'The components of spending that are not directly determined by current income in an economic model, potentially including investment, exports or public purchases.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_c22eb9c2ca338c263735f6', 'Average product', ARRAY[]::text[], 'Total output divided by the quantity of a particular input used, such as units produced per worker. It differs from the extra output attributable to one more input.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_c6e8fc6252a63c0f9f25df', 'Balanced government budget', ARRAY[]::text[], 'A fiscal position in which government revenue equals expenditure over the period under the accounting measure being used.', 'https://openstax.org/books/principles-economics-3e/pages/30-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_c986e963a560cab49000af', 'Bank bailout', ARRAY[]::text[], 'Public financial assistance or intervention intended to prevent a bank''s disorderly failure, sometimes through capital injections, guarantees or asset purchases.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_0bc97d1323a8f5febc2bea', 'Bank money', ARRAY[]::text[], 'Money held as commercial-bank deposits, which banks can create when they lend. It differs from notes, coins and central-bank reserves.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_f6b615b6fb62c13ab7326b', 'Bargaining power', ARRAY[]::text[], 'The ability of a person or organisation to secure more favourable terms in a negotiation, often because the other party has fewer acceptable alternatives.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_ca30c9155b707b7ad3365b', 'Barter', ARRAY[]::text[], 'The direct exchange of goods or services for other goods or services without using money as the medium of payment. It requires trading partners with compatible wants.', 'https://openstax.org/books/principles-economics-3e/pages/27-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_fe06c472e714cfd1386cbb', 'Beveridge curve', ARRAY[]::text[], 'A relationship between job vacancies and unemployment, usually showing more vacancies when unemployment is lower. Movements can indicate changes in matching efficiency.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_31a08738ee5317da5f2a8b', 'Biodiversity', ARRAY[]::text[], 'The variety of life within species, between species and across ecosystems. Its loss can affect food systems, natural resources and economic resilience.', 'https://www.ipcc.ch/report/ar6/wg2/chapter/annex-ii/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_c30e330938d9e87b684258', 'Biodiversity loss', ARRAY[]::text[], 'A decline in genetic, species or ecosystem diversity over time, potentially reducing natural benefits on which livelihoods and economies depend.', 'https://www.ipcc.ch/report/ar6/wg2/chapter/annex-ii/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_0b3c74064150b10cb8f410', 'Bond face value', ARRAY[]::text[], 'The principal amount specified on a bond, normally repayable at maturity unless its terms provide otherwise. It can differ from the bond''s current market price.', 'https://openstax.org/books/principles-economics-3e/pages/17-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_e04b32053e213785d5c4ad', 'Bondholder', ARRAY[]::text[], 'An investor who owns a debt security issued by a company or government and is entitled to payments under the bond''s terms, subject to the issuer''s ability to pay.', 'https://openstax.org/books/principles-economics-3e/pages/17-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_09cef4c73fb220b44a6ef6', 'Break-even point', ARRAY[]::text[], 'An output and price combination at which total revenue covers all relevant costs, including opportunity costs in the economic definition of profit.', 'https://openstax.org/books/principles-economics-3e/pages/8-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_8d75c0c28845aed2fa847e', 'Bretton Woods system', ARRAY[]::text[], 'The post-1944 international monetary arrangement built around fixed but adjustable exchange rates, with the US dollar linked to gold. Its central exchange-rate rules ended in the early 1970s.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_fed1ae48cc3b6df23ddfd5', 'Broad money', ARRAY[]::text[], 'A measure of the money stock including cash and a wide range of bank deposits or other liquid monetary claims, depending on national definitions.', 'https://www.imf.org/en/about/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_3c8182942940d59f65b5bf', 'Capacity utilisation rate', ARRAY[]::text[], 'The proportion of potential productive capacity currently in use, given existing equipment and operating conditions. Low utilisation may indicate weak demand.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_52aad198380e7605884180', 'Capital adequacy ratio', ARRAY[]::text[], 'A regulatory measure of a bank''s capital relative to its risk-weighted exposures. It indicates the bank''s capacity to absorb losses under the applicable supervisory rules.', 'https://www.bis.org/committees/bcbs/basel-framework/standard/bcp', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_66d7f48d25bf93e6055c7e', 'Capital depreciation', ARRAY[]::text[], 'The loss of value or productive capacity of physical capital through wear, ageing or obsolescence, often included as a cost in national accounts.', 'https://openstax.org/books/principles-economics-3e/pages/19-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_396e56e6194b55dce9b57a', 'Capital goods', ARRAY[]::text[], 'Durable equipment, buildings and other produced assets used to make further goods and services rather than being consumed immediately.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_a03e190179892bff0cf81b', 'Capital productivity', ARRAY[]::text[], 'Output produced per unit of productive capital used, such as the value of output relative to machinery or equipment.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_6cfdee99ece1b97c89c42d', 'Capital-intensive production', ARRAY[]::text[], 'Production that relies relatively heavily on machinery, infrastructure or other physical capital rather than labour for each unit of output.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_a5780e07f2b1bef15824c2', 'Carbon border adjustment mechanism', ARRAY['CBAM']::text[], 'A policy that applies a carbon-related charge or obligation to selected imports to address differences in emissions costs between domestic and foreign production.', 'https://taxation-customs.ec.europa.eu/carbon-border-adjustment-mechanism_en', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_0cdae1e15a268007a5df0d', 'Carbon budget', ARRAY[]::text[], 'An estimate of cumulative carbon dioxide emissions consistent with limiting global warming to a specified level and probability, given scientific assumptions.', 'https://www.ipcc.ch/sr15/chapter/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_34125495a19af04459566e', 'Carbon capture and storage', ARRAY['CCS']::text[], 'The capture of carbon dioxide from industrial or energy-related sources followed by transport and durable storage, typically underground. It can reduce emissions from those sources.', 'https://www.ipcc.ch/sr15/chapter/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_52714654b82d7ff7973c61', 'Carbon capture and utilisation', ARRAY['CCU']::text[], 'The capture of carbon dioxide for use in products or processes. Whether it reduces emissions depends on the source, energy used and fate of the captured carbon.', 'https://www.ipcc.ch/sr15/chapter/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_b5b66df5c193014b6b3b43', 'Carbon cycle', ARRAY[]::text[], 'The movement of carbon between the atmosphere, oceans, land, living organisms and geological stores through physical, chemical and biological processes.', 'https://www.ipcc.ch/sr15/chapter/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_7062ed00f1448c9244fc42', 'Carbon intensity', ARRAY[]::text[], 'Carbon dioxide emissions per unit of activity, such as electricity generated, output produced or GDP. Lower intensity does not necessarily mean lower total emissions.', 'https://www.ipcc.ch/sr15/chapter/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_f6948cab11cea246513553', 'Carbon leakage', ARRAY[]::text[], 'The shift of emissions-intensive production to places with weaker carbon constraints, potentially reducing the worldwide benefit of a policy in one jurisdiction.', 'https://taxation-customs.ec.europa.eu/carbon-border-adjustment-mechanism_en', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_240e06d97bc0272e73ad22', 'Carbon sequestration', ARRAY[]::text[], 'The capture or uptake and storage of carbon in forests, soils, geological formations or other reservoirs. Durability and measurement matter for climate claims.', 'https://www.ipcc.ch/sr15/chapter/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_773dd45a885aca68a8bfc2', 'Carbon sink', ARRAY[]::text[], 'A natural or engineered system that takes up more carbon than it releases over a period, such as a growing forest or managed storage reservoir.', 'https://www.ipcc.ch/sr15/chapter/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_86d0eb0e3bccac7a8fecd9', 'Catch-up growth', ARRAY[]::text[], 'Faster economic growth in a poorer economy that reduces its output or income gap with more productive economies, when institutions and technology allow convergence.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_f5c18273a21b97ab534815', 'Categorical inequality', ARRAY[]::text[], 'Economic disparities between social groups defined by characteristics such as region, ethnicity or gender, as distinct from inequality among individuals generally.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_6a20d7ac16dec0f23d0682', 'Certificate of deposit', ARRAY[]::text[], 'A bank deposit that generally commits money for a specified term in exchange for an agreed rate of interest. Early withdrawals may be restricted or penalised.', 'https://openstax.org/books/principles-economics-3e/pages/17-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_4a407f1097f66016440be1', 'Ceteris paribus', ARRAY[]::text[], 'A Latin phrase meaning ''other things being equal''. Economists use it to study the effect of one change while holding other relevant influences constant.', 'https://openstax.org/books/principles-economics-3e/pages/3-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_8e6354026d29724a69e858', 'Climate change adaptation', ARRAY[]::text[], 'Adjustments to actual or expected climate impacts, such as flood protection or heat-resilient infrastructure, intended to reduce harm or exploit opportunities.', 'https://www.ipcc.ch/report/ar6/wg2/chapter/annex-ii/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_5b0afee46257f6e79c50c2', 'Climate change mitigation', ARRAY[]::text[], 'Actions intended to reduce greenhouse-gas emissions or increase removals, thereby limiting the extent of climate change.', 'https://www.ipcc.ch/sr15/chapter/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_1c8c2c6f0dcd9fcbeb0cbc', 'Climate finance', ARRAY[]::text[], 'Public or private funding intended to reduce greenhouse-gas emissions, increase removals or strengthen adaptation to climate change, including cross-border assistance.', 'https://unfccc.int/topics/introduction-to-climate-finance', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_9168f4c4da898dac8059bc', 'Climate resilience', ARRAY[]::text[], 'The capacity of people, institutions or systems to anticipate, withstand, adapt to and recover from climate-related shocks and longer-term changes.', 'https://www.ipcc.ch/report/ar6/wg2/chapter/annex-ii/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_e024affc46b3a9ad4e89e5', 'Climate scenario analysis', ARRAY[]::text[], 'The evaluation of how alternative, internally consistent climate and policy pathways could affect an organisation, market or economy over time.', 'https://www.ipcc.ch/report/ar6/wg2/chapter/annex-ii/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_10999038029ae738a31f6f', 'Climate stress testing', ARRAY[]::text[], 'An assessment of how severe but plausible climate-related shocks or transition pathways could affect financial institutions or portfolios.', 'https://www.ecb.europa.eu/ecb-and-you/explainers/html/why_climate_change_matters.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_20841fea2bb027a5890343', 'Climate transition risk', ARRAY[]::text[], 'Economic or financial risk arising from adjustment to a low-carbon economy, including policy changes, new technologies and shifts in demand.', 'https://www.ecb.europa.eu/ecb-and-you/explainers/html/why_climate_change_matters.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_1f29f8525f1ad80355e6a1', 'Climate vulnerability', ARRAY[]::text[], 'The tendency of a person, community or system to suffer harm from climate hazards, shaped by sensitivity and the ability to cope or adapt.', 'https://www.ipcc.ch/report/ar6/wg2/chapter/annex-ii/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_fcb9823f09f80e83a0b493', 'Club good', ARRAY[]::text[], 'A good for which access can be restricted but additional users impose little cost until capacity becomes scarce, such as a lightly used subscription service.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_e692fa652930e1a6e58931', 'Codified knowledge', ARRAY[]::text[], 'Technical knowledge recorded in a form that others can read and reproduce, such as a documented manufacturing process or scientific formula.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_5390a6642da6a5d150306a', 'Collateralised debt obligation', ARRAY['collateralized debt obligation']::text[], 'A structured security backed by a portfolio of loans or debt instruments, divided into classes that absorb losses in different orders. It can concentrate complex credit risks.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_ebcd55af55613eaafd848a', 'Commodity money', ARRAY[]::text[], 'An item used as money that also has a use or value apart from its monetary role, such as a commodity historically accepted in trade.', 'https://openstax.org/books/principles-economics-3e/pages/27-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_12495dfe9881e3a292eaf6', 'Commodity-backed currency', ARRAY[]::text[], 'Money whose value is supported by an issuer''s commitment to exchange it for a specified commodity, such as gold, under defined conditions.', 'https://openstax.org/books/principles-economics-3e/pages/27-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_07435be0f0c4fedfed1eb1', 'Common-pool resource', ARRAY[]::text[], 'A resource that is difficult to exclude people from using but becomes less available to others when it is consumed, such as an unregulated fishery.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_756a14a867b45f9ddac6eb', 'Complementary goods', ARRAY['complements']::text[], 'Products commonly consumed together, such as printers and ink. A rise in the price of one typically reduces demand for the other.', 'https://openstax.org/books/principles-economics-3e/pages/3-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_6811ad9c8a9f5d9935cdff', 'Concentration ratio', ARRAY[]::text[], 'The combined market share held by the largest firms in an industry, often the top four or eight. It provides a simple measure of market concentration.', 'https://openstax.org/books/principles-economics-3e/pages/11-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_a502c7e1e82b628c002202', 'Conspicuous consumption', ARRAY[]::text[], 'Buying goods or services partly to display wealth or social status to other people, rather than solely for their direct usefulness.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_085644e314c7d4362dda0e', 'Constant returns to scale', ARRAY[]::text[], 'A production relationship in which increasing every input by the same proportion increases total output by that proportion, with technology held constant.', 'https://openstax.org/books/principles-economics-3e/pages/7-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_f18409d6762943064cc5aa', 'Constrained optimisation', ARRAY[]::text[], 'Choosing the best attainable outcome according to an objective while respecting limits such as available time, income, technology or resources.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_3e406f2dfc805eea1b4040', 'Consumer durable', ARRAY[]::text[], 'A consumer good intended to provide services over several years, such as a household appliance or car, rather than being used up immediately.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_28143157a73e374ec725cf', 'Consumer equilibrium', ARRAY[]::text[], 'A consumer''s affordable combination of goods that provides the greatest attainable satisfaction given their preferences, income and prevailing prices.', 'https://openstax.org/books/principles-economics-3e/pages/6-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_2e6938604569a6e37faa70', 'Consumption function', ARRAY[]::text[], 'A relationship describing how household consumption changes with disposable income or other influences, central to simple Keynesian models.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_5065e23c43037603ec856a', 'Contingent valuation', ARRAY[]::text[], 'A survey method that asks people how much they would pay or accept for a change in a non-market good, such as cleaner air or protected habitat.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_2ae41fa6dbd644a6846389', 'Copyright', ARRAY[]::text[], 'A legal right protecting original creative works, generally giving their owner control over copying and certain other uses for a limited period, subject to exceptions.', 'https://openstax.org/books/principles-economics-3e/pages/9-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_68ab8319234739c7c2eeac', 'Corporate acquisition', ARRAY['business acquisition']::text[], 'A transaction in which one company purchases control of another, often through acquiring shares or assets. It can be friendly or contested.', 'https://openstax.org/books/principles-economics-3e/pages/11-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_d9a3e8541c17c995ce7c8a', 'Corporate governance', ARRAY[]::text[], 'The rules, institutions and processes through which a company''s shareholders and board oversee its executives. Good governance aims to align management decisions with the firm''s responsibilities and long-term interests.', 'https://openstax.org/books/principles-economics-3e/pages/17-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_ca930b0f8b3cca32c8705e', 'Corporate income tax', ARRAY[]::text[], 'A tax charged on taxable profits earned by companies, with rates, deductions and tax bases differing across jurisdictions.', 'https://openstax.org/books/principles-economics-3e/pages/30-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_6dc88a75586495e2ae80f0', 'Corporate merger', ARRAY['business merger']::text[], 'The combination of two previously separate companies into one business or group. Competition authorities may investigate mergers that substantially reduce competition.', 'https://openstax.org/books/principles-economics-3e/pages/11-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_bb2b6d2bde6250e6dced0b', 'Cost-plus regulation', ARRAY[]::text[], 'A regulatory approach allowing a utility or other firm to charge prices that recover approved costs plus an allowed return, potentially weakening incentives to control costs.', 'https://openstax.org/books/principles-economics-3e/pages/11-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_9dfee993b1352e468d2218', 'Countercyclical policy', ARRAY[]::text[], 'Economic policy intended to lean against the business cycle, supporting demand in downturns and restraining excess demand in booms.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_ee429dcdab4085bd5c57e4', 'Credit constraint', ARRAY[]::text[], 'A restriction on how much a person or business can borrow, or on the terms available, relative to what they would choose without financing limits.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_fcb5d4d85d70067de2c6bf', 'Credit exclusion', ARRAY[]::text[], 'A situation in which a person or firm cannot obtain a loan from available lenders at any offered terms, even though they wish to borrow.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_a3f4a1f351a6108762be82', 'Demand curve', ARRAY[]::text[], 'A graph showing how much of a good buyers are willing and able to purchase at different prices, holding other influences on demand constant.', 'https://openstax.org/books/principles-economics-3e/pages/3-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_66792fe31de83fe161568c', 'Demand deposit', ARRAY[]::text[], 'A deposit balance that the account holder can normally withdraw or use for payments on demand, rather than committing it for a fixed term.', 'https://openstax.org/books/principles-economics-3e/pages/27-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_b79b3db6ac484bef7b23fb', 'Demand schedule', ARRAY[]::text[], 'A table listing the quantities of a good demanded at different prices, assuming other determinants of demand do not change.', 'https://openstax.org/books/principles-economics-3e/pages/3-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_01d24a19059bed93b745f1', 'Demand shock', ARRAY[]::text[], 'An unexpected change in total spending, such as a sudden fall in business investment or a surge in exports, that affects output and employment.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_8fe53816cb2ea4f47bb51e', 'Democratic accountability', ARRAY[]::text[], 'The use of elections, legislative scrutiny and other democratic mechanisms to make political decision-makers answerable to citizens.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_f4c0965a0c9a50bec7806f', 'Demographic transition', ARRAY[]::text[], 'The shift from high birth and death rates to low ones as a society develops, often creating a temporary period of rapid population growth.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_28a72dddc5543d22769234', 'Depository institution', ARRAY[]::text[], 'A financial institution that accepts deposits and uses part of its funding to extend loans or make other investments, subject to the rules governing its business.', 'https://openstax.org/books/principles-economics-3e/pages/27-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_930cd0853e92f143fcab80', 'Developmental state', ARRAY[]::text[], 'A government that actively guides industrial development through investment, coordination and selective support for sectors rather than relying on markets alone.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_160dfd8775e3ef1b35e9f4', 'Diffusion gap', ARRAY[]::text[], 'The delay between an innovation''s first appearance and its widespread adoption, which can limit the speed of economy-wide productivity growth.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_f555bbd1bf70cc66622f6f', 'Diffusion of innovation', ARRAY[]::text[], 'The spread of a new technology or practice across firms, consumers or regions after it is first introduced, sometimes over many years.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_b9d794d1ae1e50ef7be6ae', 'Diminishing marginal returns', ARRAY['law of diminishing returns']::text[], 'A production pattern in which each additional unit of a variable input eventually adds less output when other inputs are held fixed.', 'https://openstax.org/books/principles-economics-3e/pages/7-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_4b20f383dda832c873b21f', 'Direct air capture', ARRAY[]::text[], 'A technology that separates carbon dioxide from ambient air. If the captured gas is durably stored, the process can contribute to carbon dioxide removal.', 'https://www.ipcc.ch/sr15/chapter/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_bc116417a483ae2891b9c3', 'Discretionary fiscal policy', ARRAY[]::text[], 'Deliberate changes to tax or government spending rules intended to influence economic activity, as opposed to the automatic response of existing policies.', 'https://openstax.org/books/principles-economics-3e/pages/30-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_f947fbded4b367cf3d83f8', 'Distributionally neutral policy', ARRAY[]::text[], 'A policy designed or assessed to leave the relative distribution of income or resources broadly unchanged across groups.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_b7e91ba106e5ed4dca7db3', 'Dominant strategy', ARRAY[]::text[], 'A choice that gives a player at least as high a payoff as any alternative, regardless of what other players choose in a game.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_481fd5589b9d8ac66532b4', 'Dominant-strategy equilibrium', ARRAY[]::text[], 'A game outcome in which each player follows a dominant strategy. It is a Nash equilibrium, but not every Nash equilibrium arises from dominant strategies.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_ecbf644657f39160d98847', 'Double coincidence of wants', ARRAY[]::text[], 'A condition for direct barter in which each trading partner has something the other wants. The difficulty of finding such matches helps explain why money is useful.', 'https://openstax.org/books/principles-economics-3e/pages/27-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_204c5b6a4361cf06c386d8', 'Economic accountability', ARRAY[]::text[], 'Pressure on decision-makers to respond to customers, workers or investors through market processes such as competition, losses or withdrawal of support.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_93cba3e294326d27ba3159', 'Economic institutions', ARRAY[]::text[], 'The formal laws and informal social rules that shape how people and businesses interact, including property rights, contract enforcement and norms.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_2d6be3b347f2b69459ab88', 'Economic multiplier process', ARRAY[]::text[], 'The chain of successive changes in spending and income set off by an initial change in demand, creating a total output effect that may exceed the first impulse.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_62ddee5a4a19cc121d5ca9', 'Economically feasible policy', ARRAY[]::text[], 'A policy whose intended outcome is consistent with the incentives of those affected, so participants do not immediately undermine it through their choices.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_d54eafdc74e6b6a4ed6dd2', 'Economies of agglomeration', ARRAY[]::text[], 'Productivity or cost advantages firms obtain by locating near other businesses and workers, including access to suppliers, talent and knowledge spillovers.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_b82d6cc33e09572127f575', 'Economies of scope', ARRAY[]::text[], 'Cost advantages from producing several products together rather than in separate firms, often because they share equipment, distribution or expertise.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_6e5b95fd3c465fedb78b3a', 'Ecosystem services', ARRAY[]::text[], 'Benefits people derive from ecosystems, including pollination, water purification, soil formation and climate regulation, many of which are not traded directly.', 'https://www.ipcc.ch/report/ar6/wg2/chapter/annex-ii/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_3edaedcb16198c4e5a1321', 'Elastic demand', ARRAY[]::text[], 'Demand for which quantity changes proportionately more than price, with absolute price elasticity greater than one over the interval considered.', 'https://openstax.org/books/principles-economics-3e/pages/5-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_50f55b474aaeab277efa4c', 'Elastic supply', ARRAY[]::text[], 'Supply for which the percentage change in quantity supplied exceeds the percentage change in price, giving a price elasticity greater than one.', 'https://openstax.org/books/principles-economics-3e/pages/5-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_cb84939f9828d33e88a06d', 'Emissions abatement', ARRAY[]::text[], 'Actions that prevent, reduce or reverse pollution or greenhouse-gas emissions relative to what would otherwise occur, through changes in behaviour, technology or production.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_ee6d29628c274ddd75a218', 'Emissions allowance', ARRAY[]::text[], 'A tradable authorisation to emit a specified amount of greenhouse gases under a regulated emissions trading scheme. It differs from a credit representing an emissions reduction.', 'https://carbonpricingdashboard.worldbank.org/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_bd58cd09056ca5f2c0724c', 'Employment rent', ARRAY[]::text[], 'The extra benefit a worker obtains from their current job compared with their next best alternative. Losing the job would remove this benefit.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_40e536c8ebc4f04bb1ca84', 'Environmental justice', ARRAY[]::text[], 'The fair distribution of environmental benefits and harms and meaningful participation in decisions affecting communities, particularly those facing disproportionate burdens.', 'https://www.ipcc.ch/report/ar6/wg2/chapter/annex-ii/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_7c79942b28b0b8a40d27d9', 'Environmental tipping point', ARRAY[]::text[], 'A threshold beyond which a small further change can trigger a self-reinforcing and potentially difficult-to-reverse shift in an environmental system.', 'https://www.ipcc.ch/report/ar6/wg2/chapter/annex-ii/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_f5119e097d6cebc5c78ced', 'Equilibrium price', ARRAY[]::text[], 'The price at which the quantity demanded equals the quantity supplied in a market, given prevailing demand and supply conditions.', 'https://openstax.org/books/principles-economics-3e/pages/3-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_9de8c4b984308e603de4de', 'Equilibrium quantity', ARRAY[]::text[], 'The amount of a good bought and sold when a market is at its equilibrium price, where planned demand equals planned supply.', 'https://openstax.org/books/principles-economics-3e/pages/3-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_7422d9bee888c0562e4f25', 'Estate tax', ARRAY[]::text[], 'A tax charged on the value of a deceased person''s estate, or on transfers of wealth at death, subject to jurisdiction-specific rules and thresholds.', 'https://openstax.org/books/principles-economics-3e/pages/30-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_8de99b386fe4c385e616b0', 'Excess bank reserves', ARRAY[]::text[], 'Reserve balances held by banks above any required minimum, which can affect the banking system''s liquidity and monetary policy implementation.', 'https://openstax.org/books/principles-economics-3e/pages/28-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_5e35e509fbdd57cf282362', 'Excess demand', ARRAY['market shortage']::text[], 'A situation in which buyers wish to purchase more than sellers offer at the current price. Other things equal, it creates upward pressure on price.', 'https://openstax.org/books/principles-economics-3e/pages/3-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_973110cbd6a60379ca8350', 'Excess supply', ARRAY['market surplus']::text[], 'A situation in which sellers offer more than buyers wish to purchase at the current price. Other things equal, it creates downward pressure on price.', 'https://openstax.org/books/principles-economics-3e/pages/3-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_78786f023cbe7d1a999dac', 'Excise tax', ARRAY[]::text[], 'A tax levied on particular goods or activities, such as fuel or alcohol, often charged per unit rather than as a broad sales tax.', 'https://openstax.org/books/principles-economics-3e/pages/30-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_0382119afe1830ff6dbad1', 'Expected rate of return', ARRAY[]::text[], 'The gain or loss an investor anticipates on an investment relative to the amount invested, including expected income and changes in asset value. Actual returns can differ.', 'https://openstax.org/books/principles-economics-3e/pages/17-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_c9089997f182a4e06e1979', 'Explicit cost', ARRAY['explicit costs']::text[], 'A direct monetary payment made to obtain resources for production, such as wages, rent or materials. It appears in conventional financial accounts.', 'https://openstax.org/books/principles-economics-3e/pages/7-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_56fbd183fc1e1033719b03', 'Exposure to climate hazards', ARRAY[]::text[], 'The presence of people, assets, infrastructure or ecosystems in places where climate-related hazards may cause damage.', 'https://www.ipcc.ch/report/ar6/wg2/chapter/annex-ii/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_c14672e10e11919df7db81', 'External economies of scale', ARRAY[]::text[], 'Cost or productivity advantages that firms obtain because an entire industry or local cluster expands, rather than because an individual firm grows.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_286aa81883c964cdbcf74a', 'Factors of production', ARRAY['production inputs']::text[], 'Resources used to make goods and services, traditionally grouped as labour, capital, land and entrepreneurship. Their availability influences productive capacity.', 'https://openstax.org/books/principles-economics-3e/pages/3-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_3d9aee0aa78707eafff8a7', 'Fallacy of composition', ARRAY[]::text[], 'The mistake of assuming that what is beneficial or true for one individual must also hold when everyone acts in the same way.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_545a0ca51c124332f07607', 'Feasible frontier', ARRAY[]::text[], 'The boundary of the feasible set, showing the greatest achievable amount of one outcome for a specified level of another.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_a0a6aaf9488389bcfc27e8', 'Feasible set', ARRAY[]::text[], 'The collection of choices or allocations that satisfy all relevant constraints, including physical, economic and legal restrictions.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_c5a00fbf0091cf8146646a', 'Final good', ARRAY[]::text[], 'A good or service purchased for final use rather than as an input to other production. Measuring final goods avoids counting intermediate output repeatedly.', 'https://openstax.org/books/principles-economics-3e/pages/19-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_67efb0a9eb9c084b926ee2', 'Financial accelerator', ARRAY[]::text[], 'A mechanism in which economic shocks change borrowers'' net worth or collateral values, affecting credit availability and amplifying the original shock.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_e83d31abbaffbdf6503b15', 'Financial deregulation', ARRAY[]::text[], 'The relaxation or removal of legal restrictions on financial institutions or markets, such as rules governing products, prices or permitted activities.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_562f6771818eebca196847', 'Financial insolvency', ARRAY[]::text[], 'A condition in which a person or organisation cannot meet debts as they fall due or has liabilities exceeding assets, depending on the legal and accounting test.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_6a3a4d9e11654c39fe7936', 'Financial solvency', ARRAY[]::text[], 'The condition of having sufficient assets to cover liabilities, or meeting the relevant legal test for ability to pay debts. Solvency differs from having cash immediately available.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_b5c4f75b797446203834e5', 'Fire sale of assets', ARRAY[]::text[], 'The rapid sale of assets at distressed prices because an owner urgently needs cash, potentially imposing losses elsewhere in the financial system.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_1650b0b407d52d51996802', 'Fiscal capacity', ARRAY[]::text[], 'A government''s ability to raise and administer tax revenue effectively. It depends on institutions, enforcement, record-keeping and public compliance.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_5a2e503399aaff643df79a', 'Fisher equation', ARRAY[]::text[], 'A relationship connecting nominal interest, real interest and expected inflation. In the common approximation, the real rate equals the nominal rate minus expected inflation.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_6822168bae5267d45fb36c', 'Fixed input', ARRAY[]::text[], 'A productive resource whose quantity cannot be readily changed over the relevant short-run period, such as an existing factory building.', 'https://openstax.org/books/principles-economics-3e/pages/7-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_9a3cdc9ee8fe7e83382dd6', 'Fundamental share valuation', ARRAY[]::text[], 'An assessment of a share''s value based on expected future payments or earnings and the risks involved, rather than simply its current market price.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_a289d56bb2634b095b33ac', 'Gains from trade', ARRAY[]::text[], 'The benefits parties receive from voluntary exchange compared with their next best alternatives. They arise when parties value the traded items differently.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_3e6cd9a8cf20267941bc82', 'Game payoff', ARRAY[]::text[], 'The benefit, cost or utility a player receives from a particular combination of strategies selected by the participants in a game.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_86f4cc4823fc2067ecbd72', 'Gold standard', ARRAY[]::text[], 'A monetary system in which the value of a currency is defined by a specified quantity of gold and, under its rules, can be exchanged at that rate.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_229fd6159cadd154d263f0', 'Golden age of capitalism', ARRAY[]::text[], 'The decades after the Second World War through the early 1970s, marked in many advanced economies by rapid growth, strong employment and rising real wages.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_8a74fc3fa52795533c5132', 'Government budget surplus', ARRAY[]::text[], 'A fiscal outcome in which government revenue exceeds total expenditure over a period, reducing the financing need for that period.', 'https://openstax.org/books/principles-economics-3e/pages/30-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_1016976dca00671d8a9fe9', 'Government transfers', ARRAY[]::text[], 'Payments such as pensions or unemployment support made by government without purchasing goods or services in return. They are distinct from government consumption.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_44ac9d7cb7ab9eb1e80064', 'Great Moderation', ARRAY[]::text[], 'A period of relatively low volatility in output and inflation in several advanced economies before the global financial crisis of 2007–09.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_d44ddadb085fd4b3dda010', 'Great Recession', ARRAY[]::text[], 'The severe economic downturn surrounding the global financial crisis of 2007–09, which brought major losses in output and employment in many countries.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_7faeaacd43573b7946e093', 'Green adjustment to national income', ARRAY[]::text[], 'An adjustment to conventional income measures that accounts for changes in the value of natural resources or environmental assets.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_75b662429e90c460041903', 'Green bond', ARRAY[]::text[], 'A bond whose proceeds are intended to finance or refinance eligible projects with environmental benefits, subject to the issuer''s commitments and applicable standards.', 'https://www.icmagroup.org/sustainable-finance/the-principles-guidelines-and-handbooks/green-bond-principles-gbp', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_7d05779654cafb65241d0a', 'Greenhouse gas', ARRAY[]::text[], 'An atmospheric gas that absorbs and re-emits infrared radiation, contributing to the greenhouse effect. Carbon dioxide and methane are important human-influenced examples.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_3d59cb1accaa3fec7313c4', 'Gross national product', ARRAY[]::text[], 'The market value of final output associated with a country''s residents, including income attributable to their production abroad. It differs from domestic production measured by GDP.', 'https://openstax.org/books/principles-economics-3e/pages/19-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_e42fc972d26c67f6faea1b', 'Hedge finance', ARRAY[]::text[], 'In Hyman Minsky''s classification of financing, a position where expected cash inflows can cover both interest and scheduled principal repayments without refinancing.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_ac8e2e92ef92269d1bfb74', 'Hedonic pricing', ARRAY[]::text[], 'A method that estimates the value of product or environmental attributes by examining how they influence observed market prices, such as house prices.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_b1476638bb18d6cd6d19a0', 'Household net worth', ARRAY[]::text[], 'The market value of a household''s assets, including property and investments, minus its outstanding debts. It measures accumulated wealth rather than annual income.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_9e9ab965376d31a41d390a', 'Human capital investment', ARRAY[]::text[], 'Spending time or money on education, training or health that can raise a person''s productive abilities and expected future earnings.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_d11cf7aef8800478ce5da5', 'Idiosyncratic risk', ARRAY[]::text[], 'Risk specific to a company or small set of assets, such as a product failure. A well-diversified portfolio can reduce exposure to much of it.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_272d69b9d8fd73887820c2', 'Imperfect competition', ARRAY[]::text[], 'A market situation between perfect competition and monopoly in which one or more firms can affect prices, for example through differentiated products or concentration.', 'https://openstax.org/books/principles-economics-3e/pages/10-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_1300db9e6c16d4312b05f8', 'Implementation lag', ARRAY[]::text[], 'The delay between adopting a fiscal measure and getting the spending or other policy change into effect.', 'https://openstax.org/books/principles-economics-3e/pages/30-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_41bf7cb8e9c9e3d1548638', 'Implicit cost', ARRAY['implicit costs']::text[], 'The opportunity cost of using resources the firm already owns, such as the return an owner could have earned by working elsewhere.', 'https://openstax.org/books/principles-economics-3e/pages/7-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_ae0559d99e068c55b12ad8', 'Implicit labour contract', ARRAY[]::text[], 'An unwritten understanding between an employer and employee about how wages, job security or working conditions may evolve, particularly during economic shocks.', 'https://openstax.org/books/principles-economics-3e/pages/21-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_1d3c20a2e8153b0c4624ed', 'In-kind transfer', ARRAY[]::text[], 'Government support delivered through goods or services rather than cash payments, such as subsidised healthcare or housing.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_f43da0897e585663407bb7', 'Incentive crowding out', ARRAY[]::text[], 'A situation where a financial incentive weakens an existing intrinsic or social motivation, sometimes reducing the behaviour the incentive was intended to encourage.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_ed3ff9b07228f777bd1d65', 'Incomplete contract', ARRAY[]::text[], 'An agreement that cannot specify or enforce every relevant action or contingency, leaving scope for discretion and bargaining after it is signed.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_d6f45215ce0d1a346f0aeb', 'Incremental innovation', ARRAY[]::text[], 'A series of relatively small improvements to existing products or processes, which can accumulate into substantial productivity or quality gains.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_463255082195d5fb14f28b', 'Inelastic demand', ARRAY[]::text[], 'Demand for which quantity changes proportionately less than price, with absolute price elasticity below one over the interval considered.', 'https://openstax.org/books/principles-economics-3e/pages/5-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_40963869003221b6e41eb9', 'Inelastic supply', ARRAY[]::text[], 'Supply for which producers change quantity proportionately less than the change in price, giving a price elasticity below one.', 'https://openstax.org/books/principles-economics-3e/pages/5-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_f7c5d76c55e4377b3946bf', 'Inflationary gap', ARRAY[]::text[], 'A situation in which aggregate demand pushes output above a sustainable potential level, creating pressure for wages and prices to increase.', 'https://openstax.org/books/principles-economics-3e/pages/25-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_0d58cdf5d6031c9247efb3', 'Innovation rents', ARRAY[]::text[], 'Extra profits earned by innovators who introduce a new product, process or organisation before competitors can replicate the advantage.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_5a62358d08283bd82d8aab', 'Innovation system', ARRAY[]::text[], 'The network of firms, universities, governments, researchers and rules that shapes the creation and spread of new technologies.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_7d6b8d087764bdc0feea71', 'Insider-outsider model', ARRAY[]::text[], 'A labour-market theory in which existing employees have advantages over potential replacements, affecting wage bargaining and the employment prospects of outsiders.', 'https://openstax.org/books/principles-economics-3e/pages/21-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_13a7258789187301de21f4', 'Intergenerational climate equity', ARRAY[]::text[], 'A fairness principle considering how climate policy choices today distribute costs, risks and benefits between people alive now and future generations.', 'https://www.ipcc.ch/report/ar6/wg2/chapter/annex-ii/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_4b70761e676bc417b58c5e', 'Intergenerational income elasticity', ARRAY[]::text[], 'A measure of how strongly earnings or income differences among parents are associated with differences among their adult children. Higher values suggest less mobility.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_e0e38136a9f8eeebed11ad', 'Intergenerational mobility', ARRAY[]::text[], 'Changes in economic or social status between parents and their children. Greater mobility means family background is less predictive of adult outcomes.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_26b5ec30416be9ccbe4ba1', 'Intermediate good', ARRAY[]::text[], 'A product purchased for use in producing another good or service, such as steel used to make a car. Its value is not added again when final output is counted.', 'https://openstax.org/books/principles-economics-3e/pages/19-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_17d5b1a6f20426b60ad622', 'Inventory investment', ARRAY[]::text[], 'The change in the value of unsold goods and materials held by firms over a period. In national accounts it can contribute positively or negatively to investment.', 'https://openstax.org/books/principles-economics-3e/pages/19-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_cae7fffe325d11aaee193a', 'Irrational exuberance', ARRAY[]::text[], 'Excessive market optimism that pushes asset valuations well above levels justified by reasonable expectations of future income and risk.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_c6c164b189b7fb0a4e67ba', 'Joint surplus', ARRAY[]::text[], 'The combined economic benefits received by the participants in an interaction relative to their outside options, before considering how the benefits are divided.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_07b9132209dd877ae60028', 'Kinked demand curve', ARRAY[]::text[], 'A model of oligopoly in which competitors are expected to match price cuts but not increases, making demand more responsive to increases than reductions in a firm''s price.', 'https://openstax.org/books/principles-economics-3e/pages/10-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_638f1b4ef0e3fc8969a063', 'Labour discipline model', ARRAY[]::text[], 'A framework in which employers set pay to make job loss costly enough that workers have an incentive to supply effort even when their actions cannot be monitored perfectly.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_980769dc70da6e28b8e460', 'Labour force', ARRAY[]::text[], 'People who are employed or unemployed and actively seeking work, under the relevant statistical definition. It excludes those outside the labour market.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_48a22f99e84439e7bf77e7', 'Labour market equilibrium', ARRAY[]::text[], 'A situation in which wage-setting behaviour and firms'' employment decisions are mutually consistent, given economic conditions and institutions.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_700626390cccf64114f438', 'Labour market mismatch', ARRAY[]::text[], 'A gap between the skills or locations of jobseekers and those demanded by employers, which can coexist with both vacancies and unemployment.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_8ef197b4f967bc07cee1d9', 'Labour productivity growth', ARRAY[]::text[], 'An increase over time in the quantity or value of output produced per hour worked or per worker, which can help support higher living standards.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_fb6b88857a1ad635f44a6f', 'Labour-intensive production', ARRAY[]::text[], 'Production that uses relatively more labour and less machinery or equipment than alternative methods for producing a comparable output.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_7641a93b78265ec3c00cf8', 'Law of one price', ARRAY[]::text[], 'The principle that identical tradable goods should have the same price in connected markets once currency conversion and relevant transaction costs are accounted for.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_4fb378e418e5493834e46a', 'Learning by doing', ARRAY[]::text[], 'Improvement in productivity or skills as workers and firms gain experience through repeated production or practice.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_59ed0996b0e144ff09025b', 'Legal monopoly', ARRAY[]::text[], 'A market position protected from certain competition by law, such as an exclusive licence or specified intellectual-property rights.', 'https://openstax.org/books/principles-economics-3e/pages/9-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_bfbad129ddb69e7fa16a10', 'Legislative lag', ARRAY[]::text[], 'The delay between identifying a fiscal problem and passing the legislation needed to change taxes or spending.', 'https://openstax.org/books/principles-economics-3e/pages/30-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_e94b9fb906eeff89ff85b6', 'Limited liability', ARRAY[]::text[], 'A legal arrangement in which shareholders generally risk the money they invest in a company rather than being personally responsible for all its debts. Exceptions can apply under the law.', 'https://openstax.org/books/principles-economics-3e/pages/17-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_e8324dd783d8b6ee7d7f82', 'Liquidity risk', ARRAY[]::text[], 'The possibility that an asset cannot be sold quickly at a predictable price, or that an institution cannot meet payments when they come due.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_5d443fb16a3029cd4964e8', 'Long-run aggregate supply', ARRAY[]::text[], 'A model of the economy''s sustainable productive capacity determined by resources, technology and institutions rather than the general price level.', 'https://openstax.org/books/principles-economics-3e/pages/24-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_b61f860898042c17eca721', 'Long-run production', ARRAY[]::text[], 'Production decisions over a period long enough for a firm to change all inputs, including its production facilities and scale of operations.', 'https://openstax.org/books/principles-economics-3e/pages/7-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_dec669806d902d8b34ffc4', 'Maladaptation', ARRAY[]::text[], 'An attempted response to climate change that unintentionally increases vulnerability or emissions, shifts risks to others or undermines future resilience.', 'https://www.ipcc.ch/report/ar6/wg2/chapter/annex-ii/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_77a402a07f79a7066d8be9', 'Marginal abatement cost', ARRAY[]::text[], 'The additional cost of avoiding one more unit of emissions or pollution. It helps compare options for meeting environmental targets at lower total cost.', 'https://www.ipcc.ch/sr15/chapter/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_de51bd510c6b980717d2bc', 'Marginal analysis', ARRAY[]::text[], 'Comparing the additional benefit of a small change in an action with its additional cost. It helps determine whether doing slightly more or less is worthwhile.', 'https://openstax.org/books/principles-economics-3e/pages/2-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_8689ba96c8c512e8530e4b', 'Marginal external cost', ARRAY[]::text[], 'The additional harm imposed on third parties by producing or consuming one more unit of a good, beyond the costs paid by those involved.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_0ec9de13d75cb43b67ddc2', 'Marginal private benefit', ARRAY[]::text[], 'The additional value received directly by a buyer or producer from one more unit, excluding benefits accruing to others.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_6a83f8a62bd2bf0d9affcf', 'Marginal private cost', ARRAY[]::text[], 'The extra cost of one more unit borne directly by the producer or decision-maker, excluding costs imposed on outsiders.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_01253b6cc8184772cb68ec', 'Marginal profit', ARRAY[]::text[], 'The increase in profit from selling one additional unit, calculated as marginal revenue minus marginal cost at that output level.', 'https://openstax.org/books/principles-economics-3e/pages/9-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_97df4bf40307553334d72d', 'Marginal propensity to consume', ARRAY[]::text[], 'The increase in consumer spending associated with one additional unit of disposable income. It is commonly between zero and one in basic models.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_3eee8e21f26070655a532b', 'Marginal propensity to import', ARRAY[]::text[], 'The increase in spending on imports associated with an additional unit of national income, holding other determinants constant.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_3a936a2e77d760e72c56a2', 'Marginal social benefit', ARRAY[]::text[], 'The total additional benefit of one more unit to society, including gains to the decision-maker and positive effects on others.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_6a99de70f9cc9ebf9b6752', 'Marginal social cost', ARRAY[]::text[], 'The full additional cost of one more unit to society, combining the decision-maker''s marginal private cost and any external harm.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_7908890c63809fb578b435', 'Marginal utility per pound', ARRAY[]::text[], 'The additional satisfaction from spending another pound on a good, calculated as marginal utility divided by its price. It helps explain how consumers allocate budgets.', 'https://openstax.org/books/principles-economics-3e/pages/6-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_34c84e2703d091bd94e080', 'Market entry costs', ARRAY[]::text[], 'Expenditures a new supplier must incur to begin competing in a market, such as premises, equipment or product development. High sunk entry costs can deter potential entrants.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_39c07e4e1b1da6d45caa8c', 'Market equilibrium', ARRAY[]::text[], 'A market outcome in which the quantity buyers wish to purchase equals the quantity sellers wish to supply, leaving no pressure from a shortage or surplus at that price.', 'https://openstax.org/books/principles-economics-3e/pages/3-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_5666c12dcede617f7d47a0', 'Market power', ARRAY[]::text[], 'The ability of a seller or buyer to influence the terms or price of a transaction instead of accepting an externally determined competitive price.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_4538f33a4c4282d35943e5', 'Matching market', ARRAY[]::text[], 'A market or institution that pairs participants from two groups, such as students with universities or workers with employers, based on mutual preferences.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_47da1f14e30b3ffbf1d527', 'Maturity transformation', ARRAY[]::text[], 'The practice of financing relatively long-term loans or investments using shorter-term liabilities, such as bank deposits. It creates liquidity and rollover risks.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_5f6f08729717e086a99ca3', 'Medium of exchange', ARRAY[]::text[], 'Something widely accepted as payment for goods and services, allowing people to buy and sell without arranging direct barter between matching trading partners.', 'https://openstax.org/books/principles-economics-3e/pages/27-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_fae20dea6170e068e96a83', 'Menu costs', ARRAY[]::text[], 'The costs firms incur when changing prices, including updating menus, labels or systems. They can make prices slow to adjust.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_ad99591c658b0b9a196187', 'Merit good', ARRAY[]::text[], 'A good or service considered socially desirable for people to receive even if their private demand or ability to pay is low, such as basic education.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_689b39b55bd6d3f0cf4e92', 'Momentum trading', ARRAY[]::text[], 'An investment strategy that buys securities with recent price gains or sells recent losers, aiming to profit if trends continue for a period.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_9b406ee850b8da515acbb1', 'Money multiplier', ARRAY[]::text[], 'A simplified description of how bank deposits can expand relative to an initial stock of reserves. Its textbook formula assumes a fixed reserve ratio and does not describe every modern monetary system.', 'https://openstax.org/books/principles-economics-3e/pages/27-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_40e3066e5aa81b67658e6d', 'Mortgage-backed security', ARRAY[]::text[], 'A financial instrument whose payments depend on cash flows from a pool of mortgage loans. Investors face risks including borrower defaults and early repayments.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_c056bd3ba98eaf2a8c84a6', 'Municipal bond', ARRAY[]::text[], 'A debt security issued by a city or other local public authority to raise funds, often for public infrastructure or services. Credit and tax treatment vary by issuer and jurisdiction.', 'https://openstax.org/books/principles-economics-3e/pages/17-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_dc48b6d4ea1ad5d0b9151d', 'Narrow money', ARRAY[]::text[], 'A measure of readily spendable money such as currency and transaction deposits, under the statistical definition used by the relevant central bank.', 'https://www.imf.org/en/about/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_e265927be2d90c5328cf46', 'National accounts', ARRAY[]::text[], 'A framework of statistical accounts measuring an economy''s production, income, expenditure and relationships with other sectors, including the rest of the world.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_4223962636a1544f1af9c1', 'Nationally determined contribution', ARRAY['NDC']::text[], 'A country''s communicated climate plan under the Paris Agreement, describing intended actions on emissions and often adaptation, updated over successive cycles.', 'https://unfccc.int/process-and-meetings/the-paris-agreement/nationally-determined-contributions-ndcs', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_2c11efce80824a8a46e873', 'Natural capital', ARRAY[]::text[], 'Stocks of natural resources and ecosystems that generate benefits to people and economic activity, such as forests, water and productive soils.', 'https://www.ipcc.ch/report/ar6/wg2/chapter/annex-ii/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_4ad8286b2d3119a1257b91', 'Nature-based solution', ARRAY[]::text[], 'An action that protects, restores or manages ecosystems to address societal challenges such as climate risks while benefiting people and biodiversity.', 'https://www.ipcc.ch/report/ar6/wg2/chapter/annex-ii/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_c7b8d599c8b9ee934e4273', 'Net national product', ARRAY[]::text[], 'Gross national product after subtracting consumption of fixed capital, or depreciation. It measures output net of estimated wear on productive assets.', 'https://openstax.org/books/principles-economics-3e/pages/19-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_6c322789e5f5b364a4ad35', 'Net-negative emissions', ARRAY[]::text[], 'A situation in which human activities remove more greenhouse gases from the atmosphere than they emit over a specified period, under an appropriate accounting method.', 'https://www.ipcc.ch/sr15/chapter/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_61d757a6306484a61f4a27', 'Net-zero carbon dioxide emissions', ARRAY['carbon neutrality']::text[], 'A balance between human-caused carbon dioxide emissions and removals over a specified period. This narrower goal is not the same as net zero across all greenhouse gases.', 'https://www.ipcc.ch/sr15/chapter/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_d1c7e19fed0bba44272774', 'Net-zero greenhouse-gas emissions', ARRAY[]::text[], 'A balance between human-caused greenhouse-gas emissions and human-caused removals over a specified period, using an agreed method to compare different gases.', 'https://www.ipcc.ch/sr15/chapter/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_3cccf7f11e921d63076544', 'Network economies of scale', ARRAY[]::text[], 'Advantages from a growing user base when the value of a product to existing users increases as more people join the same network.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_372c7df3acd5e7697488f0', 'Network effects', ARRAY[]::text[], 'A situation in which a product becomes more valuable to its users as more people adopt it, as with some communication or payment networks.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_70e1a4a5109122af2f1ac6', 'Nominal interest rate', ARRAY[]::text[], 'The stated interest rate on a loan or asset without adjusting for changes in the general price level. Its purchasing-power effect depends on inflation.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_2a4600ef0a6161f300b98f', 'Nominal wage', ARRAY[]::text[], 'The money amount paid to a worker before adjusting for inflation. A nominal pay rise need not imply an increase in purchasing power.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_786920874bd86e1a1733d0', 'Non-compete agreement', ARRAY[]::text[], 'A contractual restriction limiting a worker''s ability to join a competitor or start a rival business after leaving employment, subject to local law.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_311d3578427baff43f4f9b', 'Normative statement', ARRAY[]::text[], 'A claim about what ought to happen, based partly on values or judgements about desirable outcomes. Unlike a positive statement, it cannot be settled by evidence alone.', 'https://openstax.org/books/principles-economics-3e/pages/2-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_a74308c26fee652b289fe2', 'Opportunity cost of capital', ARRAY[]::text[], 'The return an owner or investor forgoes by committing funds to one activity rather than the next best available investment with comparable risk.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_9640c536a86475db9c7731', 'Order book', ARRAY[]::text[], 'A record of outstanding orders to buy and sell an asset at specified prices and quantities on an exchange or trading venue.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_0efeb0af000f41aada399d', 'Output gap', ARRAY[]::text[], 'The difference between actual and estimated potential output, often expressed as a percentage of potential GDP. A negative gap suggests spare productive capacity.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_9c8b722b51dc6a1899b2d0', 'Paradox of thrift', ARRAY[]::text[], 'The possibility that if everyone tries to save more by cutting consumption, aggregate income falls enough that total saving does not increase.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_19fa77f3fa585344f1b96c', 'Pareto dominance', ARRAY[]::text[], 'A comparison in which one outcome makes at least one person better off and nobody worse off than another outcome.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_c30f8bd3f7c2a301a30af2', 'Pareto efficiency', ARRAY[]::text[], 'A condition in which no feasible change can make one person better off without making someone else worse off. It does not imply an equitable distribution.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_d77c81c90eacbc61f8d6c0', 'Pareto improvement', ARRAY[]::text[], 'A feasible change that benefits at least one person without making anyone else worse off, according to their own preferences.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_7e22e255d7881eb41b80d4', 'Paris Agreement', ARRAY[]::text[], 'A global climate treaty adopted in 2015 under which countries submit climate plans and seek to keep warming well below 2°C while pursuing efforts to limit it to 1.5°C.', 'https://unfccc.int/process-and-meetings/the-paris-agreement', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_8f1f6224ba39be1bf6c0e8', 'Payment system', ARRAY[]::text[], 'The institutions, rules and infrastructure through which money or other claims are transferred between payers and recipients to settle transactions.', 'https://openstax.org/books/principles-economics-3e/pages/27-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_d534ae05bf5d5ff4a0326a', 'Payroll tax', ARRAY[]::text[], 'A tax or social contribution based on workers'' earnings, paid by employees, employers or both depending on the tax system.', 'https://openstax.org/books/principles-economics-3e/pages/30-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_03fd4553ccb57a409e8eea', 'Perfect competition', ARRAY[]::text[], 'A market structure with many buyers and sellers, homogeneous products and limited barriers to entry, so individual firms cannot materially influence the market price.', 'https://openstax.org/books/principles-economics-3e/pages/8-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_10acee2b668487f9792905', 'Perfectly elastic demand', ARRAY[]::text[], 'Demand that is infinitely sensitive to price at a given level, represented by a horizontal demand curve in the standard model.', 'https://openstax.org/books/principles-economics-3e/pages/5-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_83fce0ace2ee883b7d5d3c', 'Perfectly inelastic demand', ARRAY[]::text[], 'Demand that remains at the same quantity regardless of price changes over the relevant range, represented by a vertical demand curve.', 'https://openstax.org/books/principles-economics-3e/pages/5-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_5a72259b80e584e1c485b7', 'Performance-related pay', ARRAY[]::text[], 'Pay linked to measured individual or organisational performance, intended to influence incentives but sometimes encouraging an overly narrow focus on measured targets.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_45d7d7b8af54a21969d03f', 'Physical climate risk', ARRAY[]::text[], 'Financial or economic risk from climate-related hazards such as floods, heatwaves and storms, or gradual shifts in temperature, rainfall and sea level.', 'https://www.ecb.europa.eu/ecb-and-you/explainers/html/why_climate_change_matters.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_888905cca9a4e79347a4f4', 'Political institutions', ARRAY[]::text[], 'Formal and informal rules that determine who holds public power, how decisions are made and how authority is constrained.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_093df6ce601c3973107e9c', 'Political rent', ARRAY[]::text[], 'An economic benefit above someone''s next best alternative that arises from holding a privileged political position or access to government decisions.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_b415e800d5034f9c351d16', 'Polluter pays principle', ARRAY[]::text[], 'A principle of environmental policy under which those causing pollution should bear the costs of preventing, controlling or remedying the damage.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_578af9397b1ce308ac81c6', 'Positive statement', ARRAY[]::text[], 'A claim describing how the economy works or predicting what will happen, which can in principle be tested against evidence rather than relying on a value judgement.', 'https://openstax.org/books/principles-economics-3e/pages/2-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_8abfefc27b2684bce29e91', 'Potential GDP', ARRAY[]::text[], 'An estimate of the output an economy could sustain with its available workers, capital and technology without persistent upward or downward inflation pressure.', 'https://openstax.org/books/principles-economics-3e/pages/24-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_9d89b9a2878a3e3c9ea969', 'Precautionary saving', ARRAY[]::text[], 'Saving undertaken to protect consumption against uncertain future expenses, unemployment or income shocks.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_576c82f5e39ea212a24ae5', 'Predistribution policy', ARRAY[]::text[], 'Measures designed to change the distribution of earnings or wealth before taxes and transfers, such as education, labour-market rules or competition policy.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_150dbd6d76d15311dd93e2', 'Price markup', ARRAY[]::text[], 'The difference between a firm''s selling price and its relevant cost measure, often marginal cost, expressed as a monetary amount or percentage.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_1bf374c35e39ae9c98aa0f', 'Price-cap regulation', ARRAY[]::text[], 'A system in which a regulator sets an upper limit on prices, often permitting adjustments for inflation and efficiency targets over a fixed review period.', 'https://openstax.org/books/principles-economics-3e/pages/11-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_71d834ed350f0d68dab9a0', 'Price-setting curve', ARRAY[]::text[], 'A model describing the real wage consistent with firms'' chosen prices and markups at different levels of economic activity.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_80f76cf26b56d98b0a9e6d', 'Private company', ARRAY[]::text[], 'A company whose ownership interests are not publicly traded on a stock exchange. It may still have many investors or be managed by people other than its owners.', 'https://openstax.org/books/principles-economics-3e/pages/17-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_7a76f5c9b28aebd0ef2808', 'Private good', ARRAY[]::text[], 'A good that is both rival in consumption and excludable, meaning non-payers can generally be prevented from accessing it.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_71654f5f778b46cf273b8b', 'Process innovation', ARRAY[]::text[], 'The introduction of a new or improved way to produce or deliver goods and services, often reducing costs or increasing quality.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_b59ba3495fc17a7bba4627', 'Procyclical policy', ARRAY[]::text[], 'Policy that reinforces the current economic cycle, such as cutting spending during a recession or stimulating demand during an expansion.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_0c0c40850259aa755862d1', 'Product innovation', ARRAY[]::text[], 'The creation or significant improvement of a good or service that consumers value, potentially giving its producer an advantage.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_4dd2e6806c458d14ddcc4b', 'Production function', ARRAY[]::text[], 'A mathematical or graphical relationship showing the maximum output obtainable from given combinations of inputs under a particular technology.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_740a7fc87fa90bfa2bc9de', 'Production possibilities frontier', ARRAY['PPF']::text[], 'A curve showing the maximum feasible combinations of two outputs with available resources and technology. Points inside the frontier indicate unused productive capacity.', 'https://openstax.org/books/principles-economics-3e/pages/2-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_d60598b229ae81d78d4c37', 'Productive efficiency', ARRAY[]::text[], 'A situation in which an economy or firm cannot produce more of one output without giving up some other output or using additional resources.', 'https://openstax.org/books/principles-economics-3e/pages/2-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_c2e7ac8066388858de60a8', 'Proportional income tax', ARRAY[]::text[], 'A tax under which the same percentage rate applies to income regardless of the taxpayer''s income level, before any exemptions or reliefs.', 'https://openstax.org/books/principles-economics-3e/pages/30-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_24de8c90c27586dd75853d', 'Public bad', ARRAY[]::text[], 'A harmful outcome whose effects can reach many people without one person''s exposure reducing another''s, such as widespread air pollution.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_9b9c1387cc9ae356451960', 'Public company', ARRAY[]::text[], 'A company whose shares can be held by outside investors, often traded on a stock exchange. Its ownership and disclosure obligations depend on the jurisdiction and listing status.', 'https://openstax.org/books/principles-economics-3e/pages/17-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_f0de6bcfb3d36963090a71', 'Rational expectations', ARRAY[]::text[], 'The assumption that people use available information and an understanding of the economy to form forecasts without systematic, predictable mistakes.', 'https://openstax.org/books/principles-economics-3e/pages/26-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_74c0d40a08a87bf088b91d', 'Real wage', ARRAY[]::text[], 'Pay adjusted for changes in the price level. It measures how many goods and services a worker can buy with their earnings.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_f8f6ea2275eb4a93e3b885', 'Realised rate of return', ARRAY['realized rate of return']::text[], 'The return actually earned over a completed investment period, including income and changes in value, expressed relative to the investment''s starting value.', 'https://openstax.org/books/principles-economics-3e/pages/17-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_1da5fec4b348975d509dfb', 'Recessionary gap', ARRAY[]::text[], 'A shortfall of actual output below the economy''s potential level, usually associated with weak demand and underused resources.', 'https://openstax.org/books/principles-economics-3e/pages/25-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_c45b4ab7f1567e9daa20f9', 'Recognition lag', ARRAY[]::text[], 'The time policymakers need to detect and diagnose a change in economic conditions before deciding whether action is necessary.', 'https://openstax.org/books/principles-economics-3e/pages/30-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_f2c6dc0daf97641f8d0c95', 'Reservation option', ARRAY[]::text[], 'The next best alternative available to someone if a proposed transaction or relationship does not proceed. It affects bargaining power.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_59aaae96b3168fcf5912a6', 'Reservation price', ARRAY[]::text[], 'The most a buyer is willing to pay, or the least a seller is willing to accept, for a transaction given the available alternatives.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_3f07fe9feb91507170a1c3', 'Reservation wage', ARRAY[]::text[], 'The lowest pay a person would accept for a particular job, given their alternatives such as other employment, benefits or unpaid time.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_b0e336c59ef0ac68457f14', 'Residual claimant', ARRAY[]::text[], 'The person or group entitled to what remains of a project''s revenue after the agreed payments to workers, suppliers, creditors and others are made.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_33dda6d565d6645a7289d5', 'Revealed preference', ARRAY[]::text[], 'An approach that infers people''s preferences from choices they actually make, rather than relying only on what they report wanting.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_a4e030428707d36ef5bb51', 'Ricardian equivalence', ARRAY[]::text[], 'A hypothesis that households may save more when government borrowing rises because they expect future taxes. Its predictions rely on restrictive assumptions.', 'https://openstax.org/books/principles-economics-3e/pages/31-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_84a8de33d82d36e1edfa43', 'Risk-weighted assets', ARRAY[]::text[], 'A measure of bank exposures adjusted for their regulatory risk weights, used to calculate capital requirements. Higher-risk exposures generally receive greater weight.', 'https://www.bis.org/committees/bcbs/basel-framework/standard/bcp', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_d9fc9fa2bfc18cc3d4a6af', 'Rival good', ARRAY[]::text[], 'A product whose consumption by one person reduces the amount available to others, such as food or a seat on a crowded bus.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_c4ba7e2057fe5236731655', 'Separation of ownership and control', ARRAY[]::text[], 'A situation in which a company''s managers make key decisions while its shareholders own the business, creating potential differences in incentives.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_2b53e18f3579562b5da1df', 'Sequential game', ARRAY[]::text[], 'A strategic situation in which players move in sequence and later players can observe some earlier decisions before choosing their own actions.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_c0c485920ec024ebcabe6c', 'Shareholder', ARRAY[]::text[], 'A person or organisation that owns shares in a company and therefore holds an ownership interest, with rights determined by the share class and applicable law.', 'https://openstax.org/books/principles-economics-3e/pages/17-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_e5323a1166b5ce206fcfb9', 'Short-run aggregate supply', ARRAY[]::text[], 'The relationship between the price level and the quantity firms are willing to produce over a period when some input costs and expectations are slow to adjust.', 'https://openstax.org/books/principles-economics-3e/pages/24-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_3cf0f79f3229921f46114f', 'Short-run production', ARRAY[]::text[], 'Production decisions over a period when at least one input, such as plant capacity, cannot be adjusted. The length of that period depends on the industry.', 'https://openstax.org/books/principles-economics-3e/pages/7-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_e656fd09173523d1aff650', 'Shutdown point', ARRAY[]::text[], 'The price and output condition at which a competitive firm is indifferent between producing and temporarily stopping in the short run. Below minimum average variable cost, shutting down limits losses.', 'https://openstax.org/books/principles-economics-3e/pages/8-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_a39c827afe6fe3802644f9', 'Simultaneous game', ARRAY[]::text[], 'A strategic interaction in which players select their actions without first observing the choices being made by the others, even if the decisions are not literally simultaneous.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_ed4f96a1320bd901f3b7eb', 'Social dilemma', ARRAY[]::text[], 'A situation in which choices that benefit individuals acting separately produce an outcome worse for the group than a feasible cooperative alternative.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_4270f00a60bdaef8856bbc', 'Social norm', ARRAY[]::text[], 'A shared expectation within a group about appropriate behaviour, which can shape choices through approval, disapproval or internalised values.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_c27e7517b3caefd24a4d3f', 'Social preferences', ARRAY[]::text[], 'Preferences in which people care about others'' outcomes or fairness as well as their own material payoff, helping explain cooperation and charitable behaviour.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_7f339c7d1648607734ea87', 'Sovereign debt crisis', ARRAY[]::text[], 'A situation in which a government''s ability to service or refinance its borrowing is seriously threatened, potentially requiring restructuring, external support or default.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_b51cb630131aab297a4f46', 'Speculative finance', ARRAY[]::text[], 'In Hyman Minsky''s framework, financing where expected cash inflows cover interest but not all principal repayments, so debt must be refinanced or rolled over.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_349715a8c84436a673cc75', 'Stable equilibrium', ARRAY[]::text[], 'An equilibrium towards which a system tends to return after a small disturbance, provided the underlying relationships have not changed.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_f7ddda6b437e41b16087a3', 'Store of value', ARRAY[]::text[], 'An asset or instrument that allows purchasing power to be carried into the future. Inflation or changes in its market value can reduce how well it performs this function.', 'https://openstax.org/books/principles-economics-3e/pages/27-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_c15c71a843792e962ed760', 'Stranded asset', ARRAY[]::text[], 'An asset that loses economic value before the end of its expected useful life because of market, technological, regulatory or environmental change.', 'https://www.ecb.europa.eu/ecb-and-you/explainers/html/why_climate_change_matters.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_345dbfa966a97058c9a709', 'Strategic complements', ARRAY[]::text[], 'Actions for which one participant''s higher level of activity increases the incentive for another participant to do more of the same or a related activity.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_76ea3a3cdc737ca1b4d89a', 'Strategic interaction', ARRAY[]::text[], 'A situation in which each participant''s outcome depends partly on the choices made by others, so each must consider others'' likely behaviour.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_9ae65ad972903365dc20c7', 'Strategic substitutes', ARRAY[]::text[], 'Actions for which one participant''s higher level of activity reduces another participant''s incentive to undertake a similar or related action.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_6830c0157fc31291a440cf', 'Subprime borrower', ARRAY[]::text[], 'A borrower considered to have relatively high credit risk, often based on a history of missed payments or other indicators of weaker creditworthiness.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_f323050249314e79beeb23', 'Subprime mortgage', ARRAY[]::text[], 'A home loan made to a borrower assessed as having a relatively high risk of default, often because of a weak credit history or limited repayment capacity.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_dcd976b42470f444d16fba', 'Substitute goods', ARRAY['substitutes']::text[], 'Products that buyers can use in place of each other. A rise in the price of one generally increases demand for the other, other factors unchanged.', 'https://openstax.org/books/principles-economics-3e/pages/3-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_443a34660715c6be03fde3', 'Supply curve', ARRAY[]::text[], 'A graph showing how much producers are willing to offer for sale at different prices, holding other influences on supply constant.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_9f05e62386a70da764520e', 'Supply shock', ARRAY[]::text[], 'An unexpected change affecting production costs or capacity, such as an energy-price surge or major technological improvement, that shifts aggregate supply.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_15ddf6a6737241e0c74e44', 'Sustainability-linked bond', ARRAY[]::text[], 'A bond whose financial or structural features may change according to whether the issuer meets specified sustainability performance targets.', 'https://www.icmagroup.org/sustainable-finance/the-principles-guidelines-and-handbooks/sustainability-linked-bond-principles-slbp', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_90a96f1bbfb3c2e7e3c892', 'Systematic market risk', ARRAY[]::text[], 'Risk affecting most financial assets at once, such as an economy-wide recession. Broad diversification cannot fully remove it.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_3acca3703d9e0cd2621f5c', 'Systemic financial risk', ARRAY[]::text[], 'The possibility that problems at one institution or market propagate across the financial system, threatening credit, payments or economic activity.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_437a76d6b41e23d86df727', 'Tacit knowledge', ARRAY[]::text[], 'Practical skills and understanding that are difficult to record fully in written instructions, often learned through experience or working alongside others.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_7f3af4403f84fa6de2c242', 'Technological lock-in', ARRAY[]::text[], 'A situation in which switching costs and network benefits make it difficult to move away from an established technology even when alternatives might be better.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_a2984174c957e75938f6df', 'Too big to fail', ARRAY[]::text[], 'A description of an institution whose disorderly collapse could severely damage the financial system, creating expectations of extraordinary government support.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_025093ac67eac7814a002f', 'Total utility', ARRAY[]::text[], 'The overall satisfaction a consumer derives from a combination of goods and services, as represented in a utility model.', 'https://openstax.org/books/principles-economics-3e/pages/6-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_deeda3cdf40dcd179e6ed5', 'Trade costs', ARRAY[]::text[], 'Costs of buying or selling across borders, including transport, insurance, tariffs and administrative barriers, which can sustain price gaps between markets.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_360ea12d4e724e9fa8c34e', 'Trade mark', ARRAY['trademark']::text[], 'A legally protected sign, word or design that distinguishes the goods or services of one business from those of others.', 'https://openstax.org/books/principles-economics-3e/pages/9-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_e343ffa7df2e201f8418a0', 'Trade secret', ARRAY['trade secrets']::text[], 'Confidential business information that has economic value because it is secret and is subject to reasonable steps to keep it confidential.', 'https://openstax.org/books/principles-economics-3e/pages/9-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_65433d09aa847dd70fcc6a', 'Tragedy of the commons', ARRAY[]::text[], 'A problem in which individually rational use of an accessible shared resource depletes it, harming the group when effective rules or cooperation are absent.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_f3de6211e238e80f0afabf', 'Twin deficits', ARRAY[]::text[], 'The simultaneous presence of a government budget deficit and a current-account or trade deficit. Their connection depends on national saving and investment.', 'https://openstax.org/books/principles-economics-3e/pages/31-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_cbae10defba5e2ba78f039', 'Underemployment', ARRAY[]::text[], 'A situation in which someone works fewer hours than they wish or in a job that makes insufficient use of their skills, depending on the measure used.', 'https://openstax.org/books/principles-economics-3e/pages/21-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_a8ba8f6318b9fc302fca7b', 'Union density', ARRAY[]::text[], 'The proportion of employees who belong to a trade union. It is distinct from the share covered by collective bargaining agreements.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_5a6cb64c3ded7ee518d907', 'Unit of account', ARRAY[]::text[], 'A common measure in which prices, debts and financial records are expressed. A currency usually serves as the unit of account in its economy.', 'https://openstax.org/books/principles-economics-3e/pages/27-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_73dda1661da9b6d3528dba', 'Unit-elastic demand', ARRAY['unitary elasticity of demand']::text[], 'Demand for which the percentage change in quantity exactly matches the percentage change in price in magnitude, so absolute price elasticity equals one.', 'https://openstax.org/books/principles-economics-3e/pages/5-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_68baf979209366189190a4', 'Unstable equilibrium', ARRAY[]::text[], 'An equilibrium from which a small disturbance can push the system progressively further away, rather than back towards the starting state.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_60f0c20c6a6fe0111c6b38', 'Value added', ARRAY[]::text[], 'The value of a firm''s output minus the value of purchased intermediate inputs. Summing value added across producers is one way to calculate GDP.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_2388eb9a1029f049f05d72', 'Variable input', ARRAY[]::text[], 'A productive resource whose quantity a firm can adjust over the relevant period, such as hours of casual labour or raw materials.', 'https://openstax.org/books/principles-economics-3e/pages/7-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_91030c77192fc4bc77ec38', 'Wage inflation', ARRAY[]::text[], 'The rate at which nominal pay rises over time. It can affect household income and firms'' labour costs, and is distinct from inflation in consumer prices.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_3924b20ccd5e34cc6bab6b', 'Wage-price spiral', ARRAY[]::text[], 'A sequence in which rising wages push up prices and rising prices prompt further wage demands, potentially sustaining inflation.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_c4f6e8645aa4fc6f40974d', 'Wage-setting curve', ARRAY[]::text[], 'A model showing the real wage firms must pay at different levels of employment to motivate workers, taking account of their alternatives outside the job.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_e3752e4e0b710510ff70c9', 'Willingness to accept', ARRAY[]::text[], 'The lowest compensation a person would require to give up a good, service or entitlement, given the alternatives they face.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_dea00cdcad047adecc2810', 'Willingness to pay', ARRAY[]::text[], 'The maximum amount someone would voluntarily give up to obtain a good, service or benefit, reflecting their preferences and available resources.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_2bfcffc8e52d41d1ccf657', 'Winner-take-all competition', ARRAY[]::text[], 'Competition in which one or a few early leaders capture a large share of a market, often reinforced by networks, increasing returns or user habits.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26c_b92e2dd8a6fcfaeb668f3e', 'Zero-sum game', ARRAY[]::text[], 'A game in which one player''s gain is exactly offset by other players'' losses, so the sum of payoffs is constant across outcomes.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc'))
